sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        var id = current.trade_case_id;
        var task = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        // Check if any one of the reason code or advice or suspend is not empty
        //task.addEncodedQuery("trade_task_type=Maker^reason_codeISNOTEMPTY^ORadvice!=^ORsuspend!=^trade_case_id=" + id);
        //task.addEncodedQuery("trade_task_type=Maker^reason_codeISNOTEMPTY^ORadvice!=^ORsuspend!=^ORoutcome=Settle Trade^trade_case_id=" + id);
        task.addEncodedQuery('trade_task_type=Maker^trade_case_id=' + id);
        // Fetch the latest record
        task.orderByDesc('number');
        task.query();
        if (task.next()) {
            //MSSCUSTODY-4936
            if (task.outcome == "No remediation of corresponding Switch trade possible - put each 'Trade on Hold'" && current.ghss_trade_ref_id == task.corresponding_switch_trade_id_ref.getDisplayValue().toString()) {
                current.corresponding_switch_trade_advice = task.corresponding_switch_trade_advice;
                current.corresponding_switch_trade_reason_code = task.corresponding_switch_trade_reason_code;
                current.corresponding_switch_trade_reason_description = task.corresponding_switch_trade_reason_description;
                current.corresponding_switch_trade_suspend = task.corresponding_switch_trade_suspend;
                current.reason_code = task.corresponding_switch_trade_reason_code;
                current.reason_description = task.corresponding_switch_trade_reason_description;
                current.advice = task.corresponding_switch_trade_advice;
                current.suspend = task.corresponding_switch_trade_suspend;
                //MSSCUSTODY-4936
            } else {
                current.advice = task.advice;
                current.suspend = task.suspend;
                current.reason_code = task.reason_code;
                current.reason_description = task.reason_description;
                current.cancel_by = task.cancel_by; //MSSCUSTODY-3937
                current.cancellation_reference = task.cancellation_reference;
                current.collect_cancel_charge = task.collect_cancel_charge;
                current.settlement_type = task.settlement_type;
                current.auto_resume_indicator = task.auto_resume_indicator;
                current.bk_to_bk_info = task.bk_to_bk_info;
                // MSSCUSTODY-4148 - Add GCS fields update
                current.fxr_td = task.fxr_td;
                current.value_date = task.value_date;
                current.settlement_date = task.settlement_date;
				//MSSCUSTODY-6087
				current.fx_cx = task.fx_cx;
				current.gdi_indicator = task.gdi_indicator;
            }
        }

    } catch (error) {
        gs.info("unexpected error in BR:" + error);
    }
})(current, previous);
